@page "/settings"
@rendermode InteractiveServer

@using sv_fdeea66da62142c0970e5ccd3cee1ef9.Components.Pages.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <aside class="settings-nav">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetSection" />
    </aside>
    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetSection(string section) => _activeSection = section;
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
