namespace sv_fdeea66da62142c0970e5ccd3cee1ef9.Services;

/// <summary>
/// In-memory implementation for demonstration. Replace with a real data store.
/// </summary>
public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("John Doe", "john@example.com", "https://i.pravatar.cc/150?img=3", "Software developer and open source enthusiast.");
    private NotificationPrefs _notificationPrefs = new(true, true, false, ["general", "announcements", "random", "engineering", "design"]);
    private SecuritySettings _security = new(false, DateTime.UtcNow.AddDays(-30), [
        new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
        new("sess-2", "Firefox on macOS", "London, UK", DateTime.UtcNow.AddHours(-2)),
        new("sess-3", "Mobile Safari", "Tokyo, JP", DateTime.UtcNow.AddDays(-1))
    ]);
    private AppearanceSettings _appearance = new("Light", "Medium", "en", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_security);

    public Task ChangePasswordAsync(string currentPassword, string newPassword) => Task.CompletedTask;

    public Task RevokeSessionAsync(string sessionId)
    {
        _security = _security with
        {
            Sessions = _security.Sessions.Where(s => s.Id != sessionId).ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

